def strategy(history, rng):
    n = len(history)

    # --- opening: cooperate, but immediately punish a first-round defection ---
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    # --- cheap behavioural features over whole match ---
    opp_C = 0
    my_C = 0
    my_D = 0
    opp_D = 0
    for i in range(n):
        m, o = history[i]
        if o == 'C':
            opp_C += 1
        else:
            opp_D += 1
        if m == 'C':
            my_C += 1
        else:
            my_D += 1

    opp_rate = opp_C / n
    my_rate = my_C / n

    # --- how strongly does opponent mirror my previous action? ---
    # mimic = opponent this round equals my previous action
    mimic_hits = 0
    punish_hits = 0   # opponent defects right after I defect
    forgive_hits = 0  # opponent cooperates right after I cooperate
    opp_d_after_my_C = 0
    opp_c_after_my_D = 0
    my_D_events = 0
    my_C_events = 0
    for i in range(1, n):
        prev_me = history[i - 1][0]
        cur_op = history[i][1]
        if cur_op == prev_me:
            mimic_hits += 1
        if prev_me == 'D':
            my_D_events += 1
            if cur_op == 'D':
                punish_hits += 1
            else:
                opp_c_after_my_D += 1
        else:
            my_C_events += 1
            if cur_op == 'D':
                opp_d_after_my_C += 1
            else:
                forgive_hits += 1

    # --- trailing runs ---
    run_opp_D = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            run_opp_D += 1
        else:
            break
    run_opp_C = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            run_opp_C += 1
        else:
            break

    remaining = 100 - n
    last_me, last_opp = history[-1]

    # --- terminal exploitation: last two rounds ---
    if remaining <= 0:
        return 'C'
    if remaining == 1:
        # final round: take the 5 if opponent likely cooperates
        return 'D' if opp_rate > 0.35 else 'D'
    if remaining == 2:
        # second-to-last: defect into cooperators, cooperate against defectors
        return 'D' if opp_rate > 0.5 else 'C'

    # --- very persistent defector: best response is defect ---
    if n >= 8 and opp_C == 0:
        return 'D'
    if n >= 12 and opp_rate * 6 < 1 and run_opp_D >= 2:
        return 'D'

    # --- generous cooperator: farm mutual cooperation, exploit at end ---
    if n >= 8 and opp_rate > 0.9:
        # if they never defected at all, defect freely near the end
        if opp_D == 0:
            if remaining <= 6:
                return 'D'
            return 'C'
        # they rarely defect; keep cooperation, punish isolated defections
        if last_opp == 'D':
            return 'D'
        return 'C'

    # --- detect approximate tit-for-tat: mirror of my previous move ---
    # high mimic ratio and low random defections
    if n >= 6 and my_D_events > 0 and my_C_events > 0:
        mimic_ratio = mimic_hits / (n - 1)
        if mimic_ratio > 0.85 and opp_rate > 0.6:
            # against TFT, cooperate mostly; defect rarely when their last was C
            if last_opp == 'D':
                return 'C'
            if remaining <= 4:
                return 'D'
            if n >= 30 and rng.random() < 0.06:
                return 'D'
            return 'C'
        # detect grim-trigger-like: after my first D, they never came back
        if my_D_events >= 1:
            # find their last C
            last_c = -1
            for i in range(n):
                if history[i][1] == 'C':
                    last_c = i
            first_d_me = -1
            for i in range(n):
                if history[i][0] == 'D':
                    first_d_me = i
                    break
            if first_d_me >= 0 and last_c < first_d_me:
                return 'D'

    # --- general play ---
    # If opponent just defected:
    if last_opp == 'D':
        if run_opp_D >= 4:
            # long defection war: alternate to probe for reconciliation
            return 'C' if rng.random() < 0.25 else 'D'
        if run_opp_D == 1:
            # single defection: punish once but be forgiving if our last was also D
            if last_me == 'D':
                return 'C'
            return 'D'
        if run_opp_D == 2:
            return 'D' if rng.random() < 0.7 else 'C'
        return 'D'

    # Opponent just cooperated:
    # If we just defected and they still cooperated, they're forgiving/cooperative.
    if last_me == 'D':
        # avoid spooking a nice opponent into permanent defection
        if my_D_events > n / 3:
            return 'C'
        return 'C'

    # Both cooperating. Consider occasional probing against very nice opponents.
    if opp_rate > 0.7 and n > 25 and remaining > 10:
        # rare probing to test for TFT-like punishment
        if rng.random() < 0.05:
            return 'D'
    return 'C'
